-- ============================================================================
-- FinTrack AI — Phase 2, step 1: pgvector embeddings + user-scoped retrieval.
-- Run once in the Supabase SQL editor (or via CLI). Idempotent.
-- Embeddings are generated by the `embed` Edge Function (Gemini text-embedding-004,
-- 768 dims) — never in the client.
-- ============================================================================

create extension if not exists vector with schema extensions;

-- Embedding of a compact txn summary, e.g. "₹300 groceries at DMart on 2026-06-30, expense".
alter table transactions add column if not exists embedding vector(768);

-- Approximate-NN index for cosine distance (HNSW builds fine on an empty table).
create index if not exists transactions_embedding_idx
  on transactions using hnsw (embedding vector_cosine_ops);

-- --- User-scoped similarity search -----------------------------------------
-- SECURITY INVOKER (default) + explicit user_id filter + underlying RLS all mean
-- a caller can ONLY ever retrieve their own transactions. The Edge Function calls
-- this with the user's JWT, so auth.uid() resolves to that user.
create or replace function match_transactions(
  query_embedding vector(768),
  match_count int default 8,
  from_date date default null,
  to_date date default null
)
returns table (
  id uuid,
  merchant text,
  amount numeric,
  type text,
  txn_date date,
  category text,
  similarity float
)
language sql
stable
set search_path = public, extensions
as $$
  select
    t.id,
    t.merchant,
    t.amount,
    t.type,
    t.txn_date,
    coalesce(c.name, 'Uncategorized') as category,
    1 - (t.embedding <=> query_embedding) as similarity
  from transactions t
  left join categories c on c.id = t.category_id
  where t.user_id = auth.uid()
    and t.embedding is not null
    and (from_date is null or t.txn_date >= from_date)
    and (to_date  is null or t.txn_date <= to_date)
  order by t.embedding <=> query_embedding
  limit greatest(1, least(match_count, 50));
$$;

-- Let signed-in users call it; RLS + the user_id filter keep it scoped.
grant execute on function match_transactions(vector, int, date, date) to authenticated;
